/** Stream paginated items (async-enumerable with PaginationResult) */
export function useListItemPagesInfinite(query?: { pageSize?: number }) {
  const api = useApiService();
  return useInfiniteQuery({
    queryKey: itemsKeys.listItemPagesInfinite(query),
    queryFn: async ({ pageParam }: { pageParam: string | undefined }) => {
      const result = await api.items.listItemPagesPage(query, pageParam ? { 'x-continuation': pageParam } : undefined);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    getNextPageParam: (lastPage) => lastPage.continuationToken ?? undefined,
    initialPageParam: undefined as string | undefined,
  });
}

/** Get logs for an item with filters (path + query, no streaming) */
export function useGetItemLogs(itemId: string, query?: { logLevel?: 'debug' | 'info' | 'warn' | 'error'; from?: Date }, options?: Omit<UseQueryOptions<ItemLogs, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: itemsKeys.getItemLogs(itemId, query),
    queryFn: async () => {
      const result = await api.items.getItemLogs(itemId, query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!itemId,
    ...options,
  });
}

/** Search items by date-time range (date-time query params) */
export function useSearchItems(query?: { createdAfter?: Date; createdBefore?: Date }, options?: Omit<UseQueryOptions<Items, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: itemsKeys.search(query),
    queryFn: async () => {
      const result = await api.items.searchItems(query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}